"""Independent direct-orbit cycle lifting and frontier head marginal checks."""
import hashlib,json,os,platform,resource,subprocess,tempfile,time
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(os.environ.get('RULE30_REPLAY_ROOT',Path.cwd())).resolve()
OUT=Path(os.environ.get('RULE30_REPLAY_OUTPUT','/tmp/rule30_head_age_independent.json'))
INP='results/problem1/20260905_periodic_rational_verification.json'
def sha(b):return hashlib.sha256(b).hexdigest()
def canon(v):return json.dumps(v,sort_keys=True,separators=(',',':')).encode()
def A(v):
    bits=[int(c) for c in bin(v)[2:]] if v else []
    return sum(((bits[i-2] if i>=2 else 0)^((bits[i-1] if i else 0)|b))<<(len(bits)-1-i) for i,b in enumerate(bits))
def T(v):return v^((v<<1)|(v<<2))
def children(v):return {T(v),T(v)^1,T(v)^1^(2 if v%2==0 else 0)}
def canonical_cycle(c):
    i=c.index(min(c));return tuple(c[i:]+c[:i])
def orbit_cycle(seed):
    path=[];seen={};v=seed
    while v not in seen:
        seen[v]=len(path);path.append(v);v=A(v)
    return canonical_cycle(path[seen[v]:]),len(path),seen[v]
def main():
    start=time.monotonic();resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30))
    cycle_rows=[{'width':1,'cycles':[[1]],'cycle_count':1,'cycle_states':1,'direct_orbit_states_checked':1}]
    parents=[(1,)];first_split=None
    for width in range(2,17):
        assert time.monotonic()-start<120
        cs=set();checks=0;extensions=[]
        for parent in parents:
            got=set()
            for e in (0,1):
                c,n,t=orbit_cycle(2*parent[0]+e);checks+=n;got.add(c);cs.add(c)
                assert tuple(c[i]>>1 for i in range(len(c)))==tuple(parent[i%len(parent)] for i in range(len(c))) or set(v>>1 for v in c)==set(parent)
            extensions.append({'parent_cycle':list(parent),'child_cycles':[list(c) for c in sorted(got)]})
        assert sum(map(len,cs))<=1<<16
        assert all(len(c)&(len(c)-1)==0 for c in cs)
        cycle_rows.append({'width':width,'cycles':[list(c) for c in sorted(cs)],'cycle_count':len(cs),'cycle_states':sum(map(len,cs)),'extensions':extensions,'direct_orbit_states_checked':checks})
        if any(len(e['child_cycles'])==2 for e in extensions):
            first_split={'width':width,'extensions':[e for e in extensions if len(e['child_cycles'])==2]};break
        parents=sorted(cs)
    levels={};head_tests=0;rows=[]
    for phase,root in (('p',3),('u',1)):
        ls={1:{root}}
        for k in range(2,10):ls[k]={c for v in ls[k-1] for c in children(v)}
        levels[phase]=ls
        for h in range(1,10):
            current=set(ls[h])
            for k in range(h,10):
                assert {v>>(2*(k-h)) for v in ls[k]}==current
                assert all(v.bit_length()==(2*h if phase=='p' else 2*h-1) for v in current)
                head_tests+=1;current={A(v) for v in current}
            assert {A(v) for v in ls[h]}<=ls[h]
            if h<=8:
                im=set(ls[h]);counts=[len(im)];steps=0
                while True:
                    nxt={A(v) for v in im}
                    assert nxt<=im
                    if nxt==im:break
                    im=nxt;counts.append(len(im));steps+=1
                cores={orbit_cycle(v)[0] for v in im}
                assert {v for c in cores for v in c}==im
                width=2*h if phase=='p' else 2*h-1
                full=next((s for s in cycle_rows if s['width']==width),None)
                equal=(im=={v for c in full['cycles'] for v in c}) if full else None
                rows.append({'phase':phase,'h':h,'width':width,'initial_frontier':sorted(ls[h]),'image_counts':counts,'stabilization_age':steps,'core':sorted(im),'core_cycles':[list(c) for c in sorted(cores)],'equals_full_width_cycles':equal})
    old=json.loads((ROOT/INP).read_text())['result_summary'];x=int(old['x_hex'],16);k=old['k']
    prefixchecks=[]
    for h in range(1,9):
        im=set(levels['p'][h]);age=k-h
        for _ in range(age):
            nxt={A(v) for v in im}
            if nxt==im:break
            im=nxt
        head=x>>(2*age)
        prefixchecks.append({'h':h,'age':age,'head':head,'head_hex':hex(head),'ordinary_member':head in levels['p'][h],'aged_member':head in im,'aged_image':sorted(im)})
    covariance=[];strong=x
    for r,s in enumerate(old['full_orbit_hex']):
        v=x>>(2*r)
        for _ in range(2*r):v=A(v)
        lhs=int(s,16)>>(4*r);assert lhs==v
        assert int(s,16)>>(2*r)==strong
        covariance.append({'r':r,'common_high_part_hex':hex(v),'full_original_width_high_part_hex':hex(strong)})
        strong=A(A(strong))
    # Construct ordinary words for the SAME already-listed periodic points.
    core_by_key={(r['phase'],r['h']):r for r in rows}
    def ordinary_word(v,phase,h):
        if h==1:
            assert v==(3 if phase=='p' else 1);return phase
        cycle=next(c for c in core_by_key[phase,h]['core_cycles'] if v in c)
        prev=cycle[(cycle.index(v)-1)%len(cycle)]
        z,d=divmod(prev,4)
        assert z in core_by_key[phase,h-1]['core']
        return ordinary_word(z,phase,h-1)+('t' if d==0 else 'u' if d==1 else 'p')
    certificates=[]
    for row in rows:
        for v in row['core']:
            word=ordinary_word(v,row['phase'],row['h']);y=0
            for g in word:y=T(y) if g=='t' else T(y)^1 if g=='u' else T(y)^1^(2 if y%2==0 else 0)
            assert y==v and len(word)==row['h']
            certificates.append({'phase':row['phase'],'h':row['h'],'value':v,'generator_word':word})
    # Explicit truth table of the algebraic skew product, independent of cycle lists.
    for v in range(64):
        for e in (0,1):
            assert A(2*v+e)==2*A(v)+(((v>>1)&1)^((v&1)|e))
    summary={'completed':True,'validation_failures':[],'cycle_rows':cycle_rows,'first_split':first_split,'frontier_head_identity_cases':head_tests,'frontier_levels_sizes':{p:{k:len(v) for k,v in ls.items()} for p,ls in levels.items()},'frontier_core_rows':rows,'counterexample_prefix_checks':prefixchecks,'first_aged_rejection_h':next(r['h'] for r in prefixchecks if not r['aged_member']),'first_ordinary_rejection_h':next(r['h'] for r in prefixchecks if not r['ordinary_member']),'covariance_checks':covariance,'skew_product_truth_table_cases':128,'periodic_point_generator_certificates':certificates}
    summary['frontier_levels']={p:{k:sorted(v) for k,v in ls.items()} for p,ls in levels.items()}
    summary=json.loads(json.dumps(summary));source=Path(__file__).read_text()
    record={'experiment_id':'problem1-frontier-head-age-independent-20260905','timestamp_utc':datetime.now(timezone.utc).isoformat(),'git_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'question':'problem1','hypothesis':'Exact generation-age head marginals and symbolic cycle completeness; test whether each positive width has one A-cycle.','backend':'High-to-low cell A; direct orbits over two one-bit extensions; packed ordinary generators','parameters':{'cycle_widths':[1,16],'stop_uniqueness_at_first_split':True,'max_cycle_states':1<<16,'frontier_max_k':9,'frontier_core_max_h':8,'named_counterexample_prefix_h':[1,8],'wall_seconds':120,'memory_bytes':1<<30,'local_cpus':1,'additional_skew_truth_table_v':[0,63],'input':INP},'inputs':{INP:sha((ROOT/INP).read_bytes())},'hardware':{'machine':platform.machine(),'processor':platform.processor(),'cpu_count':os.cpu_count(),'peak_rss_kib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss},'software':{'python':platform.python_version(),'platform':platform.platform()},'runtime_seconds':time.monotonic()-start,'source_text':source,'result_summary':summary,'result_hashes':{'source_sha256':sha(source.encode()),'result_sha256':sha(canon(summary))},'status':'refuted' if first_split else 'finite-exhaustive','proof_scope':'The explicitly bounded cycle widths and frontier marginals; general identities and cycle lifting proved separately.','interpretation':'Generation age refines a necessary frontier condition. A finite unique-cycle result is not a theorem for every width.','limitations':['No new forced schedule or occurrence census.','Fixed leading blocks alone do not prove B_all.','No universal one-cycle or full-width-core equality claim from finite passage.']}
    OUT.parent.mkdir(parents=True,exist_ok=True);fd,tmp=tempfile.mkstemp(dir=OUT.parent,prefix=OUT.name+'.',suffix='.tmp')
    with os.fdopen(fd,'w') as f:
        json.dump(record,f,sort_keys=True,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
    os.replace(tmp,OUT)
    print(json.dumps({'output':str(OUT),'first_split':first_split,'cycles':[{k:v for k,v in r.items() if k not in ('cycles','extensions')} for r in cycle_rows],'head_cases':head_tests,'core_counts':[(r['phase'],r['h'],len(r['core']),r['stabilization_age'],r['equals_full_width_cycles']) for r in rows],'first_aged_rejection':summary['first_aged_rejection_h'],'covariance_cases':len(covariance)},sort_keys=True))
if __name__=='__main__':main()
